// AscendC InterleaveRope kernel
// Supports float16, bfloat16
//
// Computation per (B,N,S) task (D=64):
//   1. Load x[b,n,s,:64], cos, sin into UB
//   2. Cast to float32 for precision
//   3. Interleave: reorder adjacent pairs via GatherMask
//      pattern 0b01 → even positions, 0b10 → odd positions
//   4. Rotate: x_rotated = concat(-odd_half, even_half)
//   5. Output = interleaved * cos + x_rotated * sin
//   6. Cast back to original dtype, store

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t D_SIZE = 64;
constexpr int32_t HALF_D = 32;

// ---------------------------------------------------------------------------
// UB load / store helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// ---------------------------------------------------------------------------
// Kernel class
// ---------------------------------------------------------------------------

template <typename dataType>
class KernelInterleaveRope {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR y,
        int32_t B, int32_t N, int32_t S, int32_t D, int32_t cosS,
        int32_t totalTasks, int32_t tasksPerCore)
    {
        this->B = B;
        this->N = N;
        this->S = S;
        this->D = D;
        this->cosS = cosS;
        this->totalTasks = totalTasks;
        this->tasksPerCore = tasksPerCore;
        N_S = N * S;

        int64_t totalElems = static_cast<int64_t>(B) * N * S * D;
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), totalElems);
        cosGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(cos),
            static_cast<int64_t>(B) * N * cosS * D);
        sinGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sin),
            static_cast<int64_t>(B) * N * cosS * D);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), totalElems);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            pipe.InitBuffer(cosInQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            pipe.InitBuffer(sinInQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            // FP32 computation buffers
            pipe.InitBuffer(xFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(cosFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(sinFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(evenFp32Buf_, HALF_D * sizeof(float));
            pipe.InitBuffer(oddFp32Buf_, HALF_D * sizeof(float));
            pipe.InitBuffer(interleavedFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(rotatedFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(tmpFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(yFp32Buf_, D_SIZE * sizeof(float));
            // Cast buffer for fp16/bf16
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(xCastBuf_, D_SIZE * sizeof(float));
                pipe.InitBuffer(cosCastBuf_, D_SIZE * sizeof(float));
                pipe.InitBuffer(sinCastBuf_, D_SIZE * sizeof(float));
                pipe.InitBuffer(yCastBuf_, D_SIZE * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            uint32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                int32_t taskIdx = coreIdx * tasksPerCore + localIdx;
                if (taskIdx >= totalTasks) {
                    continue;
                }

                int32_t b = taskIdx / N_S;
                int32_t r = taskIdx % N_S;
                int32_t n = r / S;
                int32_t s = r % S;

                CopyIn(b, n, s);
                Compute();
                CopyOut(b, n, s);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t b, int32_t n, int32_t s)
    {
        // Load x[b,n,s,:64]
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        int64_t xOffset = (static_cast<int64_t>(b) * N + n) * S * D + static_cast<int64_t>(s) * D;
        LoadGmToUb(xInLocal_, xGM_[xOffset], static_cast<uint32_t>(D_SIZE));
        xInQueue_.EnQue(xInLocal_);

        // Load cos (with broadcasting support: cosS=1 means broadcast)
        cosInLocal_ = cosInQueue_.AllocTensor<dataType>();
        int64_t cosOffset;
        if (cosS == 1) {
            cosOffset = (static_cast<int64_t>(b) * N + n) * cosS * D;
        } else {
            cosOffset = (static_cast<int64_t>(b) * N + n) * cosS * D + static_cast<int64_t>(s) * D;
        }
        LoadGmToUb(cosInLocal_, cosGM_[cosOffset], static_cast<uint32_t>(D_SIZE));
        cosInQueue_.EnQue(cosInLocal_);

        // Load sin (with broadcasting support)
        sinInLocal_ = sinInQueue_.AllocTensor<dataType>();
        int64_t sinOffset;
        if (cosS == 1) {
            sinOffset = (static_cast<int64_t>(b) * N + n) * cosS * D;
        } else {
            sinOffset = (static_cast<int64_t>(b) * N + n) * cosS * D + static_cast<int64_t>(s) * D;
        }
        LoadGmToUb(sinInLocal_, sinGM_[sinOffset], static_cast<uint32_t>(D_SIZE));
        sinInQueue_.EnQue(sinInLocal_);
    }

    __aicore__ inline void PrepareInputFp32(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
        int32_t count)
    {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<float>();
        } else {
            dst = castBuf.Get<float>();
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        }
    }

    __aicore__ inline void FinalizeOutput(
        AscendC::LocalTensor<dataType> &dst,
        AscendC::LocalTensor<float> &src,
        int32_t count)
    {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<dataType>();
        } else {
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        }
    }

    __aicore__ inline void Compute()
    {
        // DeQue input data
        xInLocal_ = xInQueue_.DeQue<dataType>();
        cosInLocal_ = cosInQueue_.DeQue<dataType>();
        sinInLocal_ = sinInQueue_.DeQue<dataType>();

        // Get FP32 buffers for computation
        xFp32Local_ = xFp32Buf_.Get<float>();
        cosFp32Local_ = cosFp32Buf_.Get<float>();
        sinFp32Local_ = sinFp32Buf_.Get<float>();

        // Cast to FP32 for precision
        PrepareInputFp32(xFp32Local_, xInLocal_, xCastBuf_, D_SIZE);
        PrepareInputFp32(cosFp32Local_, cosInLocal_, cosCastBuf_, D_SIZE);
        PrepareInputFp32(sinFp32Local_, sinInLocal_, sinCastBuf_, D_SIZE);

        // Interleave via GatherMask: split into even-indexed and odd-indexed halves
        // Pattern: mask selects position within each group of size 2
        //   0b01 → select position 0 (even: d0,d2,...,d62)
        //   0b10 → select position 1 (odd:  d1,d3,...,d63)
        evenFp32Local_ = evenFp32Buf_.Get<float>();
        oddFp32Local_ = oddFp32Buf_.Get<float>();

        AscendC::GatherMaskParams gmParams;
        gmParams.repeatTimes = HALF_D;  // 32 pairs
        uint64_t rsvdCnt = 0;

        // Extract even elements (position 0 of each pair)
        AscendC::GatherMask(evenFp32Local_, xFp32Local_, static_cast<uint8_t>(0b01),
            false, 0, gmParams, rsvdCnt);

        // Extract odd elements (position 1 of each pair)
        AscendC::GatherMask(oddFp32Local_, xFp32Local_, static_cast<uint8_t>(0b10),
            false, 0, gmParams, rsvdCnt);

        // Build interleaved: [even(32), odd(32)]
        interleavedFp32Local_ = interleavedFp32Buf_.Get<float>();
        rotatedFp32Local_ = rotatedFp32Buf_.Get<float>();

        AscendC::DataCopy(interleavedFp32Local_, evenFp32Local_, HALF_D);
        AscendC::DataCopy(interleavedFp32Local_[HALF_D], oddFp32Local_, HALF_D);

        // Rotate: x_rotated[:32] = -interleaved[32:] (= -odd)
        //         x_rotated[32:] = interleaved[:32] (= even)
        AscendC::DataCopy(rotatedFp32Local_, oddFp32Local_, HALF_D);
        AscendC::Muls(rotatedFp32Local_, rotatedFp32Local_, -1.0f, HALF_D);
        AscendC::DataCopy(rotatedFp32Local_[HALF_D], evenFp32Local_, HALF_D);

        // Compute: y_f32 = interleaved * cos + rotated * sin
        yFp32Local_ = yFp32Buf_.Get<float>();
        tmpFp32Local_ = tmpFp32Buf_.Get<float>();

        AscendC::Mul(tmpFp32Local_, interleavedFp32Local_, cosFp32Local_, D_SIZE);
        AscendC::Mul(yFp32Local_, rotatedFp32Local_, sinFp32Local_, D_SIZE);
        AscendC::Add(yFp32Local_, tmpFp32Local_, yFp32Local_, D_SIZE);

        // Cast back to original dtype and output
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        FinalizeOutput(yOutLocal_, yFp32Local_, D_SIZE);

        // Free input tensors
        xInQueue_.FreeTensor(xInLocal_);
        cosInQueue_.FreeTensor(cosInLocal_);
        sinInQueue_.FreeTensor(sinInLocal_);

        // EnQue output
        yOutQueue_.EnQue(yOutLocal_);
    }

    __aicore__ inline void CopyOut(int32_t b, int32_t n, int32_t s)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        int64_t yOffset = (static_cast<int64_t>(b) * N + n) * S * D + static_cast<int64_t>(s) * D;
        StoreUbToGm(yGM_[yOffset], yOutLocal_, static_cast<uint32_t>(D_SIZE));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

private:
    int32_t B = 0;
    int32_t N = 0;
    int32_t S = 0;
    int32_t D = 0;
    int32_t cosS = 0;
    int32_t totalTasks = 0;
    int32_t tasksPerCore = 0;
    int32_t N_S = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> cosGM_;
    AscendC::GlobalTensor<dataType> sinGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    // TQue for double-buffered I/O
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> cosInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> sinInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;

    // FP32 computation buffers (TBuf/VECCALC)
    AscendC::TBuf<AscendC::TPosition::VECCALC> xFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cosFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sinFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> evenFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> oddFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> interleavedFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rotatedFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yFp32Buf_;

    // Cast buffers for fp16/bf16 (conditionally compiled)
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cosCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sinCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    // LocalTensor aliases
    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> cosInLocal_;
    AscendC::LocalTensor<dataType> sinInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xFp32Local_;
    AscendC::LocalTensor<float> cosFp32Local_;
    AscendC::LocalTensor<float> sinFp32Local_;
    AscendC::LocalTensor<float> evenFp32Local_;
    AscendC::LocalTensor<float> oddFp32Local_;
    AscendC::LocalTensor<float> interleavedFp32Local_;
    AscendC::LocalTensor<float> rotatedFp32Local_;
    AscendC::LocalTensor<float> tmpFp32Local_;
    AscendC::LocalTensor<float> yFp32Local_;
};

// ---------------------------------------------------------------------------
// Kernel entry point with dtype dispatch
// ---------------------------------------------------------------------------

extern "C" __global__ __aicore__ void interleave_rope(
    GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR y,
    int32_t B, int32_t N, int32_t S, int32_t D, int32_t cosS,
    int32_t totalTasks, int32_t tasksPerCore,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        KernelInterleaveRope<float> kernel;
        kernel.Init(x, cos, sin, y, B, N, S, D, cosS, totalTasks, tasksPerCore);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        KernelInterleaveRope<half> kernel;
        kernel.Init(x, cos, sin, y, B, N, S, D, cosS, totalTasks, tasksPerCore);
        kernel.Process();
    } else {
        KernelInterleaveRope<bfloat16_t> kernel;
        kernel.Init(x, cos, sin, y, B, N, S, D, cosS, totalTasks, tasksPerCore);
        kernel.Process();
    }
}
