// InterleaveRope op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_interleave_rope.h"

namespace ascend_kernel {

at::Tensor interleave_rope(
    const at::Tensor &x,
    const at::Tensor &cos,
    const at::Tensor &sin)
{
    // ---- Input validation ----
    TORCH_CHECK(x.dim() == 4, "x must be 4D (B, N, S, D)");
    TORCH_CHECK(cos.dim() == 4, "cos must be 4D (B, N, S, D) or (B, N, 1, D)");
    TORCH_CHECK(sin.dim() == 4, "sin must be 4D (B, N, S, D) or (B, N, 1, D)");
    TORCH_CHECK(
        x.scalar_type() == at::kHalf || x.scalar_type() == at::kBFloat16,
        "x must be float16 or bfloat16");
    TORCH_CHECK(cos.scalar_type() == x.scalar_type(),
        "cos must have the same dtype as x");
    TORCH_CHECK(sin.scalar_type() == x.scalar_type(),
        "sin must have the same dtype as x");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(cos.is_contiguous(), "cos must be contiguous");
    TORCH_CHECK(sin.is_contiguous(), "sin must be contiguous");

    int32_t B = static_cast<int32_t>(x.sizes()[0]);
    int32_t N = static_cast<int32_t>(x.sizes()[1]);
    int32_t S = static_cast<int32_t>(x.sizes()[2]);
    int32_t D = static_cast<int32_t>(x.sizes()[3]);

    TORCH_CHECK(D == 64, "D must be 64");

    int32_t cosS = static_cast<int32_t>(cos.sizes()[2]);
    TORCH_CHECK(cosS == 1 || cosS == S, "cos S dim must be 1 or match x S dim");

    int32_t cosB = static_cast<int32_t>(cos.sizes()[0]);
    int32_t cosN = static_cast<int32_t>(cos.sizes()[1]);
    int32_t cosD = static_cast<int32_t>(cos.sizes()[3]);
    TORCH_CHECK(cosB == B && cosN == N && cosD == D,
        "cos shape mismatch: expected [", B, ",", N, ",1-or-", S, ",", D, "]");

    int32_t sinS = static_cast<int32_t>(sin.sizes()[2]);
    TORCH_CHECK(sinS == 1 || sinS == S, "sin S dim must be 1 or match x S dim");
    TORCH_CHECK(sinS == cosS, "sin S dim must match cos S dim");

    int32_t sinD = static_cast<int32_t>(sin.sizes()[3]);
    TORCH_CHECK(sin.sizes()[0] == B && sin.sizes()[1] == N && sinD == D,
        "sin shape mismatch");

    // ---- Create output tensor ----
    at::Tensor y = at::empty_like(x);

    // ---- Tiling calculation ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    int32_t totalTasks = B * N * S;
    int32_t usedCoreNum = static_cast<int32_t>(
        std::min<int64_t>(coreNum, std::max<int64_t>(1, totalTasks)));
    int32_t tasksPerCore = (totalTasks + usedCoreNum - 1) / usedCoreNum;

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(interleave_rope, blockDim,
                    x, cos, sin, y,
                    B, N, S, D, cosS, totalTasks, tasksPerCore,
                    dtypeFlag);

    return y;
}

}  // namespace ascend_kernel
