// AscendC InterleaveRope kernel
// Supports float16, bfloat16
//
// Strategy: load even/odd elements directly from GM with stride to avoid
// UB→UB deinterleaving. The interleave rope formula:
//
//   output[i]     = x_even[i]*cos[i] - x_odd[i]*sin[i]       (i in 0..31)
//   output[i+32]  = x_odd[i]*cos[i+32] + x_even[i]*sin[i+32] (i in 0..31)
//
// where x_even[i] = x[2*i], x_odd[i] = x[2*i+1]

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t D_SIZE = 64;
constexpr int32_t HALF_D = 32;

// ---------------------------------------------------------------------------
// UB load/store helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadContiguous(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void LoadStrided(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t blockCount,
    uint32_t stride)
{
    // Load blockCount elements with stride bytes between consecutive elements
    AscendC::DataCopyExtParams copyParams;
    copyParams.blockCount = blockCount;
    copyParams.blockLen = sizeof(T);            // 1 element per block
    copyParams.srcStride = stride;              // skip stride bytes in GM
    copyParams.dstStride = 0;                   // write contiguously in UB
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreContiguous(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// ---------------------------------------------------------------------------
// Kernel class
// ---------------------------------------------------------------------------

template <typename dataType>
class KernelInterleaveRope {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR y,
        int32_t B, int32_t N, int32_t S, int32_t D, int32_t cosS,
        int32_t totalTasks, int32_t tasksPerCore)
    {
        this->B = B;
        this->N = N;
        this->S = S;
        this->D = D;
        this->cosS = cosS;
        this->totalTasks = totalTasks;
        this->tasksPerCore = tasksPerCore;
        N_S = N * S;

        int64_t totalElems = static_cast<int64_t>(B) * N * S * D;
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), totalElems);
        cosGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(cos),
            static_cast<int64_t>(B) * N * cosS * D);
        sinGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sin),
            static_cast<int64_t>(B) * N * cosS * D);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), totalElems);

        if ASCEND_IS_AIV {
            // Input queues: load even/odd halves of x separately (strided from GM)
            pipe.InitBuffer(xEvenInQueue_, BUFFER_NUM, HALF_D * sizeof(dataType));
            pipe.InitBuffer(xOddInQueue_, BUFFER_NUM, HALF_D * sizeof(dataType));
            // cos and sin are loaded contiguously (64 elements each)
            pipe.InitBuffer(cosInQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            pipe.InitBuffer(sinInQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            // Output queue
            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));

            // FP32 buffers for computation
            pipe.InitBuffer(xEvenFp32Buf_, HALF_D * sizeof(float));
            pipe.InitBuffer(xOddFp32Buf_, HALF_D * sizeof(float));
            pipe.InitBuffer(cosFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(sinFp32Buf_, D_SIZE * sizeof(float));
            // Split cos/sin into first and second halves for the rotation formula
            pipe.InitBuffer(cosFirstBuf_, HALF_D * sizeof(float));
            pipe.InitBuffer(cosSecondBuf_, HALF_D * sizeof(float));
            pipe.InitBuffer(sinFirstBuf_, HALF_D * sizeof(float));
            pipe.InitBuffer(sinSecondBuf_, HALF_D * sizeof(float));
            // Temporary buffers for computation
            pipe.InitBuffer(tmp1Buf_, HALF_D * sizeof(float));
            pipe.InitBuffer(tmp2Buf_, HALF_D * sizeof(float));
            pipe.InitBuffer(outFirstBuf_, HALF_D * sizeof(float));
            pipe.InitBuffer(outSecondBuf_, HALF_D * sizeof(float));

            // Cast buffers for fp16/bf16
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(xEvenCastBuf_, HALF_D * sizeof(float));
                pipe.InitBuffer(xOddCastBuf_, HALF_D * sizeof(float));
                pipe.InitBuffer(cosCastBuf_, D_SIZE * sizeof(float));
                pipe.InitBuffer(sinCastBuf_, D_SIZE * sizeof(float));
                pipe.InitBuffer(yCastBuf_, D_SIZE * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            uint32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                int32_t taskIdx = coreIdx * tasksPerCore + localIdx;
                if (taskIdx >= totalTasks) {
                    continue;
                }

                int32_t b = taskIdx / N_S;
                int32_t r = taskIdx % N_S;
                int32_t n = r / S;
                int32_t s = r % S;

                CopyIn(b, n, s);
                Compute();
                CopyOut(b, n, s);
            }
        }
    }

private:
    // Compute the element stride value in bytes for loading from GM
    static constexpr uint32_t kStrideBytes = 2 * sizeof(dataType);

    __aicore__ inline void CopyIn(int32_t b, int32_t n, int32_t s)
    {
        int64_t xRowOffset = (static_cast<int64_t>(b) * N + n) * S * D + static_cast<int64_t>(s) * D;

        // Load x_even[32] from x[b,n,s,:64:2] using strided DataCopyPad
        xEvenInLocal_ = xEvenInQueue_.AllocTensor<dataType>();
        LoadStrided(xEvenInLocal_, xGM_[xRowOffset], HALF_D, kStrideBytes);
        xEvenInQueue_.EnQue(xEvenInLocal_);

        // Load x_odd[32] from x[b,n,s,1:64:2] using strided DataCopyPad
        xOddInLocal_ = xOddInQueue_.AllocTensor<dataType>();
        LoadStrided(xOddInLocal_, xGM_[xRowOffset + 1], HALF_D, kStrideBytes);
        xOddInQueue_.EnQue(xOddInLocal_);

        // Load cos (with broadcasting support)
        cosInLocal_ = cosInQueue_.AllocTensor<dataType>();
        int64_t cosOffset;
        if (cosS == 1) {
            cosOffset = (static_cast<int64_t>(b) * N + n) * cosS * D;
        } else {
            cosOffset = (static_cast<int64_t>(b) * N + n) * cosS * D + static_cast<int64_t>(s) * D;
        }
        LoadContiguous(cosInLocal_, cosGM_[cosOffset], D_SIZE);
        cosInQueue_.EnQue(cosInLocal_);

        // Load sin (with broadcasting support)
        sinInLocal_ = sinInQueue_.AllocTensor<dataType>();
        int64_t sinOffset;
        if (cosS == 1) {
            sinOffset = (static_cast<int64_t>(b) * N + n) * cosS * D;
        } else {
            sinOffset = (static_cast<int64_t>(b) * N + n) * cosS * D + static_cast<int64_t>(s) * D;
        }
        LoadContiguous(sinInLocal_, sinGM_[sinOffset], D_SIZE);
        sinInQueue_.EnQue(sinInLocal_);
    }

    __aicore__ inline void CastToFp32(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
        int32_t count)
    {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<float>();
        } else {
            dst = castBuf.Get<float>();
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void CastFromFp32(
        AscendC::LocalTensor<dataType> &dst,
        AscendC::LocalTensor<float> &src,
        int32_t count)
    {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<dataType>();
        } else {
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void Compute()
    {
        // DeQue all inputs
        xEvenInLocal_ = xEvenInQueue_.DeQue<dataType>();
        xOddInLocal_ = xOddInQueue_.DeQue<dataType>();
