        AscendC::Mul(tmp1Local_, xOddFp32Local_, cosSecondLocal_, HALF_D);
        // tmp2 = x_even * sin_second
        AscendC::Mul(tmp2Local_, xEvenFp32Local_, sinSecondLocal_, HALF_D);
