// AscendC InterleaveRope kernel
// Supports float16, bfloat16
//
// Loads all 64 elements of x contiguously from GM, uses GatherMask to
// deinterleave into even/odd halves, then computes the rope rotation.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t D_SIZE = 64;
constexpr int32_t HALF_D = 32;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// ---------------------------------------------------------------------------
// Kernel
// ---------------------------------------------------------------------------

template <typename dataType>
class KernelInterleaveRope {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR y,
        int32_t B, int32_t N, int32_t S, int32_t D, int32_t cosS,
        int32_t totalTasks, int32_t tasksPerCore)
    {
        this->B = B;
        this->N = N;
        this->S = S;
        this->D = D;
        this->cosS = cosS;
        this->totalTasks = totalTasks;
        this->tasksPerCore = tasksPerCore;
        N_S = N * S;

        int64_t totalElems = static_cast<int64_t>(B) * N * S * D;
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), totalElems);
        cosGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(cos),
            static_cast<int64_t>(B) * N * cosS * D);
        sinGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sin),
            static_cast<int64_t>(B) * N * cosS * D);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), totalElems);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            pipe.InitBuffer(cosInQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            pipe.InitBuffer(sinInQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));

            // FP32 buffers
            pipe.InitBuffer(xFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(cosFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(sinFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(evenBuf_, HALF_D * sizeof(float));
            pipe.InitBuffer(oddBuf_, HALF_D * sizeof(float));
            pipe.InitBuffer(tempBuf_, D_SIZE * sizeof(float));

            // Cast buffers
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(xCastBuf_, D_SIZE * sizeof(float));
                pipe.InitBuffer(cosCastBuf_, D_SIZE * sizeof(float));
                pipe.InitBuffer(sinCastBuf_, D_SIZE * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            uint32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                int32_t taskIdx = coreIdx * tasksPerCore + localIdx;
                if (taskIdx >= totalTasks) continue;

                int32_t b = taskIdx / N_S;
                int32_t r = taskIdx % N_S;
                int32_t n = r / S;
                int32_t s = r % S;

                CopyIn(b, n, s);
                Compute();
                CopyOut(b, n, s);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t b, int32_t n, int32_t s)
    {
        // Load x[b,n,s,:64] contiguously
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        int64_t xOffset = (static_cast<int64_t>(b) * N + n) * S * D + static_cast<int64_t>(s) * D;
        LoadGmToUb(xInLocal_, xGM_[xOffset], D_SIZE);
        xInQueue_.EnQue(xInLocal_);

        // Load cos
        cosInLocal_ = cosInQueue_.AllocTensor<dataType>();
        int64_t cosOffset;
        if (cosS == 1) {
            cosOffset = (static_cast<int64_t>(b) * N + n) * cosS * D;
        } else {
            cosOffset = (static_cast<int64_t>(b) * N + n) * cosS * D + static_cast<int64_t>(s) * D;
        }
        LoadGmToUb(cosInLocal_, cosGM_[cosOffset], D_SIZE);
        cosInQueue_.EnQue(cosInLocal_);

        // Load sin
        sinInLocal_ = sinInQueue_.AllocTensor<dataType>();
        int64_t sinOffset;
        if (cosS == 1) {
            sinOffset = (static_cast<int64_t>(b) * N + n) * cosS * D;
        } else {
            sinOffset = (static_cast<int64_t>(b) * N + n) * cosS * D + static_cast<int64_t>(s) * D;
        }
        LoadGmToUb(sinInLocal_, sinGM_[sinOffset], D_SIZE);
        sinInQueue_.EnQue(sinInLocal_);
    }

    __aicore__ inline void CastToFp32(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
        int32_t count)
    {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<float>();
        } else {
            dst = castBuf.Get<float>();
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void Compute()
    {
        // DeQue inputs
        xInLocal_ = xInQueue_.DeQue<dataType>();
        cosInLocal_ = cosInQueue_.DeQue<dataType>();
        sinInLocal_ = sinInQueue_.DeQue<dataType>();

        // Get FP32 buffers
        xFp32Local_ = xFp32Buf_.Get<float>();
        cosFp32Local_ = cosFp32Buf_.Get<float>();
        sinFp32Local_ = sinFp32Buf_.Get<float>();

        CastToFp32(xFp32Local_, xInLocal_, xCastBuf_, D_SIZE);
        CastToFp32(cosFp32Local_, cosInLocal_, cosCastBuf_, D_SIZE);
        CastToFp32(sinFp32Local_, sinInLocal_, sinCastBuf_, D_SIZE);

        // Deinterleave: extract even and odd elements using GatherMask
        evenLocal_ = evenBuf_.Get<float>();
        oddLocal_ = oddBuf_.Get<float>();

        AscendC::GatherMaskParams gmParams;
        gmParams.src0BlockStride = 2;  // groups of 2 elements
        gmParams.repeatTimes = HALF_D; // 32 groups
        uint64_t rsvdCnt = 0;

        // even = elements at positions 0,2,4,...,62 (pattern 0b01 = bit 0 set)
