// AscendC InterleaveRope kernel
// Supports float16, bfloat16
//
// The host pre-interleaves x (reshape+transpose), so the kernel receives
// x_interleaved = [d0,d2,...,d62,d1,d3,...,d63].
//
// Computation per (B,N,S) task (D=64):
//   even = x_interleaved[:32]
//   odd  = x_interleaved[32:]
//   out[:32] = even * cos[:32] - odd * sin[:32]
//   out[32:] = odd * cos[32:] + even * sin[32:]

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t D_SIZE = 64;
constexpr int32_t HALF_D = 32;

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename dataType>
class KernelInterleaveRope {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR y,
        int32_t B, int32_t N, int32_t S, int32_t D, int32_t cosS,
        int32_t totalTasks, int32_t tasksPerCore)
    {
        this->B = B; this->N = N; this->S = S; this->D = D;
        this->cosS = cosS;
        this->totalTasks = totalTasks; this->tasksPerCore = tasksPerCore;
        N_S = N * S;

        int64_t totalElems = static_cast<int64_t>(B) * N * S * D;
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), totalElems);
        cosGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(cos),
            static_cast<int64_t>(B) * N * cosS * D);
        sinGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sin),
            static_cast<int64_t>(B) * N * cosS * D);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), totalElems);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            pipe.InitBuffer(cosInQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            pipe.InitBuffer(sinInQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));
            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, D_SIZE * sizeof(dataType));

            // FP32 buffers: x[64], cos[64], sin[64], out[64]
            pipe.InitBuffer(xFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(cosFp32Buf_, D_SIZE * sizeof(float));
            pipe.InitBuffer(sinFp32Buf_, D_SIZE * sizeof(float));
            // Temp buffers for half-computations
            pipe.InitBuffer(tmp1Buf_, HALF_D * sizeof(float));
            pipe.InitBuffer(tmp2Buf_, HALF_D * sizeof(float));
            pipe.InitBuffer(outFp32Buf_, D_SIZE * sizeof(float));

            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(xCastBuf_, D_SIZE * sizeof(float));
                pipe.InitBuffer(cosCastBuf_, D_SIZE * sizeof(float));
                pipe.InitBuffer(sinCastBuf_, D_SIZE * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            uint32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                int32_t taskIdx = coreIdx * tasksPerCore + localIdx;
                if (taskIdx >= totalTasks) continue;
                int32_t b = taskIdx / N_S;
                int32_t r = taskIdx % N_S;
                int32_t n = r / S, s = r % S;
                CopyIn(b, n, s);
                Compute();
                CopyOut(b, n, s);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t b, int32_t n, int32_t s)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        int64_t xOff = (static_cast<int64_t>(b) * N + n) * S * D + static_cast<int64_t>(s) * D;
        LoadGmToUb(xInLocal_, xGM_[xOff], D_SIZE);
        xInQueue_.EnQue(xInLocal_);

        cosInLocal_ = cosInQueue_.AllocTensor<dataType>();
        int64_t cosOff;
        if (cosS == 1)
            cosOff = (static_cast<int64_t>(b) * N + n) * cosS * D;
        else
            cosOff = (static_cast<int64_t>(b) * N + n) * cosS * D + static_cast<int64_t>(s) * D;
        LoadGmToUb(cosInLocal_, cosGM_[cosOff], D_SIZE);
        cosInQueue_.EnQue(cosInLocal_);

        sinInLocal_ = sinInQueue_.AllocTensor<dataType>();
        int64_t sinOff;
        if (cosS == 1)
            sinOff = (static_cast<int64_t>(b) * N + n) * cosS * D;
        else
            sinOff = (static_cast<int64_t>(b) * N + n) * cosS * D + static_cast<int64_t>(s) * D;
        LoadGmToUb(sinInLocal_, sinGM_[sinOff], D_SIZE);
        sinInQueue_.EnQue(sinInLocal_);
    }

    __aicore__ inline void CastToFp32(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
        int32_t count)
    {
        if constexpr (std::is_same_v<dataType, float>)
            dst = src.template ReinterpretCast<float>();
        else {
            dst = castBuf.Get<float>();
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void Compute()
    {
        xInLocal_ = xInQueue_.DeQue<dataType>();
        cosInLocal_ = cosInQueue_.DeQue<dataType>();
        sinInLocal_ = sinInQueue_.DeQue<dataType>();

        xFp32Local_ = xFp32Buf_.Get<float>();
        cosFp32Local_ = cosFp32Buf_.Get<float>();
        sinFp32Local_ = sinFp32Buf_.Get<float>();

        CastToFp32(xFp32Local_, xInLocal_, xCastBuf_, D_SIZE);
        CastToFp32(cosFp32Local_, cosInLocal_, cosCastBuf_, D_SIZE);
        CastToFp32(sinFp32Local_, sinInLocal_, sinCastBuf_, D_SIZE);

        // x is pre-interleaved: x[:32]=even, x[32:]=odd
        // even = xFp32Local_[0:32]
        // odd  = xFp32Local_[32:64]
        AscendC::LocalTensor<float> out = outFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> tmp1 = tmp1Buf_.Get<float>();
        AscendC::LocalTensor<float> tmp2 = tmp2Buf_.Get<float>();

        // out[:32] = even * cos[:32] - odd * sin[:32]
        AscendC::Mul(out, xFp32Local_, cosFp32Local_, HALF_D);
        AscendC::Mul(tmp1, xFp32Local_[HALF_D], sinFp32Local_, HALF_D);
        AscendC::Sub(out, out, tmp1, HALF_D);

        // out[32:] = odd * cos[32:] + even * sin[32:]
        AscendC::Mul(out[HALF_D], xFp32Local_[HALF_D], cosFp32Local_[HALF_D], HALF_D);
        AscendC::Mul(tmp1, xFp32Local_, sinFp32Local_[HALF_D], HALF_D);
        AscendC::Add(out[HALF_D], out[HALF_D], tmp1, HALF_D);

        // Output
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        if constexpr (std::is_same_v<dataType, float>)
            AscendC::DataCopy(yOutLocal_.template ReinterpretCast<dataType>(), out, D_SIZE);
        else {
            AscendC::Cast(yOutLocal_, out, AscendC::RoundMode::CAST_NONE, D_SIZE);
            AscendC::PipeBarrier<PIPE_V>();
        }

        xInQueue_.FreeTensor(xInLocal_);
        cosInQueue_.FreeTensor(cosInLocal_);
        sinInQueue_.FreeTensor(sinInLocal_);
        yOutQueue_.EnQue(yOutLocal_);
    }

    __aicore__ inline void CopyOut(int32_t b, int32_t n, int32_t s)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        int64_t yOff = (static_cast<int64_t>(b) * N + n) * S * D + static_cast<int64_t>(s) * D;
        StoreUbToGm(yGM_[yOff], yOutLocal_, D_SIZE);
        yOutQueue_.FreeTensor(yOutLocal_);
    }

private:
    int32_t B, N, S, D, cosS, totalTasks, tasksPerCore, N_S;
    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_, cosGM_, sinGM_, yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_, cosInQueue_, sinInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> xFp32Buf_, cosFp32Buf_, sinFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp1Buf_, tmp2Buf_, outFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_, cosCastBuf_, sinCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_, cosInLocal_, sinInLocal_, yOutLocal_;
    AscendC::LocalTensor<float> xFp32Local_, cosFp32Local_, sinFp32Local_;
};

extern "C" __global__ __aicore__ void interleave_rope(
    GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR y,
    int32_t B, int32_t N, int32_t S, int32_t D, int32_t cosS,
    int32_t totalTasks, int32_t tasksPerCore, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        KernelInterleaveRope<float> k;
        k.Init(x, cos, sin, y, B, N, S, D, cosS, totalTasks, tasksPerCore);
        k.Process();
    } else if (dtypeFlag == 1) {
        KernelInterleaveRope<half> k;
        k.Init(x, cos, sin, y, B, N, S, D, cosS, totalTasks, tasksPerCore);
        k.Process();
    } else {
        KernelInterleaveRope<bfloat16_t> k;
        k.Init(x, cos, sin, y, B, N, S, D, cosS, totalTasks, tasksPerCore);
        k.Process();
    }
}
